/* Persian calendar at the UI boundary; database dates remain ISO. */
const AcademyDates=(()=>{const formatter=new Intl.DateTimeFormat('en-US-u-ca-persian',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'UTC'});const digits=s=>String(s).replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c)).replace(/[٠-٩]/g,c=>'٠١٢٣٤٥٦٧٨٩'.indexOf(c));function parts(iso){const d=new Date(iso.slice(0,10)+'T12:00:00Z');if(isNaN(d))throw Error('تاریخ معتبر نیست');const p=Object.fromEntries(formatter.formatToParts(d).map(p=>[p.type,p.value]));return [+p.year,+p.month,+p.day]}function show(iso){if(!iso)return '—';try{return parts(iso).map((v,i)=>i?String(v).padStart(2,'0'):v).join('/').replace(/\d/g,c=>'۰۱۲۳۴۵۶۷۸۹'[c])}catch{return '—'}}function iso(value){let v=digits(value).trim();if(/^\d{4}-\d{2}-\d{2}$/.test(v)&&+v.slice(0,4)>1700)return v;const m=v.match(/^(\d{4})[\/.-](\d{1,2})[\/.-](\d{1,2})$/);if(!m)throw Error('تاریخ شمسی را مانند ۱۴۰۵/۰۸/۰۱ وارد کنید');const y=+m[1],mo=+m[2],day=+m[3];if(y<1200||y>1600||mo<1||mo>12||day<1||day>31)throw Error('تاریخ شمسی معتبر نیست');let lo=Date.UTC(y+621,0,1),hi=Date.UTC(y+622,11,31),target=y*10000+mo*100+day;while(lo<=hi){const mid=Math.floor((lo/86400000+hi/86400000)/2)*86400000;const s=new Date(mid).toISOString().slice(0,10),p=parts(s),n=p[0]*10000+p[1]*100+p[2];if(n===target)return s;if(n<target)lo=mid+86400000;else hi=mid-86400000}throw Error('این روز در تقویم شمسی وجود ندارد')}function today(){return new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Tehran'})}return {show,iso,today,start:iso('1405/09/01')}})();
/* Assist every date field without requiring a browser's Gregorian picker. */
document.addEventListener('input',e=>{const el=e.target;if(!el.matches('[data-persian-date]'))return;const raw=el.value.replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c)).replace(/[٠-٩]/g,c=>'٠١٢٣٤٥٦٧٨٩'.indexOf(c));if(/^\d{8}$/.test(raw))el.value=raw.slice(0,4)+'/'+raw.slice(4,6)+'/'+raw.slice(6);});
function mountPersianDatePicker(el){
 el.dataset.dateReady='true';const tools=document.createElement('span');tools.className='persian-date-picker';
 const initial=()=>{const v=el.value||AcademyDates.show(AcademyDates.today());return v.replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c)).split('/').map(Number)};
 const names=['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'];
 const day=document.createElement('select'),month=document.createElement('select'),year=document.createElement('select');
 for(const [select,label] of [[day,'روز'],[month,'ماه'],[year,'سال']]){select.setAttribute('aria-label',label);select.title=label;select.className='persian-date-part';}
 const thisYear=Number(AcademyDates.show(AcademyDates.today()).replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c)).split('/')[0]);
 for(let y=1200;y<=thisYear+10;y++)year.add(new Option(y.toLocaleString('fa-IR',{useGrouping:false}),String(y)));
 names.forEach((name,i)=>month.add(new Option(name,String(i+1))));
 function fillDays(y,m,d){let count=31;while(count>28){try{AcademyDates.iso(y+'/'+m+'/'+count);break}catch{count--}}day.innerHTML='';for(let i=1;i<=count;i++)day.add(new Option(i.toLocaleString('fa-IR'),String(i)));day.value=String(Math.min(d||1,count));}
 function sync(){const [y,m,d]=initial();if(!y||!m||!d)return;year.value=String(y);month.value=String(m);fillDays(y,m,d);}
 function write(){fillDays(Number(year.value),Number(month.value),Number(day.value));el.value=year.value+'/'+month.value.padStart(2,'0')+'/'+day.value.padStart(2,'0');el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}));}
 year.onchange=month.onchange=day.onchange=write;
 const today=document.createElement('button');today.type='button';today.textContent='امروز';today.onclick=()=>{el.value=AcademyDates.show(AcademyDates.today());sync();el.dispatchEvent(new Event('change',{bubbles:true}));};
 tools.append(day,month,year,today);el.after(tools);if(!el.value)el.value=AcademyDates.show(AcademyDates.today());sync();el.addEventListener('change',sync);
}
new MutationObserver(()=>{document.querySelectorAll('[data-persian-date]:not([data-date-ready])').forEach(mountPersianDatePicker);}).observe(document.documentElement,{childList:true,subtree:true});
